import React, { useState } from "react"

import "../../css/style.css"
import "../../css/all.min.css"
import "../../css/duotone.min.css"

import {useDraggable, useDroppable, DragDropProvider} from '@dnd-kit/react'
import {CSS} from '@dnd-kit/utilities'
import Draggable from "./Draggable.js"
import Droppable from "./Droppable.js"

import { Grid, Store, StoreElement, transformXYtoID, transformIDtoXY, SEPARATOR } from "../utils/classes.js"
import _ from "lodash"
import TopMenu from "../menu/TopMenu.js"
import CampaignMenu from "../menu/CampaignMenu.js"
import CharacterStore from "../character/CharacterStore.js"
import CharacterWidgetDetails from "../character/CharacterWidgetDetails.js"

export default function Test(props) {
    
    const [grid, setGrid] = useState(new Grid(15, 11))
    const [dragged, setDragged] = useState(null)

    function updateDragAndDrop(target) {
        let [x, y] = transformIDtoXY(target.id)

        let newGrid = _.cloneDeep(grid)
        newGrid.unselectAll()

        let tile = newGrid.getTile(x, y)
        tile.select()
        tile.setId(dragged.id)
        tile.setContent(<Draggable id={target.id} setDragged={setDragged} icon={dragged?.icon}/>)

        if(dragged && dragged.id.toString().includes(SEPARATOR)) {
            let sourceTile = newGrid.getTile(transformIDtoXY(dragged.id)[0], transformIDtoXY(dragged.id)[1])
            if(sourceTile) {
                sourceTile.removeContent()
            }
        }

        setGrid(newGrid)
    }

    return (
        <>
            <TopMenu />
            <CampaignMenu />
            <div class="std-horiz-center">
                <DragDropProvider
                    onDragEnd={event => {
                        if (event.canceled) return
                        
                        const {target} = event.operation
                        if (target) {
                            updateDragAndDrop(target)
                        }
                    }}
                >
                        {grid.Display}
                        <div class="max-30-w">
                            <CharacterWidgetDetails grid={grid}/>
                            <CharacterStore setDragged={setDragged}/>
                        </div>
                </DragDropProvider>
            </div>
        </>
    )
}