import React, { Fragment } from "react"
import Droppable from "../test/Droppable"
import Draggable from "../test/Draggable"

export const SEPARATOR = "-"

export function transformXYtoID(x, y) {
    return x.toString() + "-" + y.toString()
}

export function transformIDtoXY(id) {
    return [id.split(SEPARATOR)[0], id.split(SEPARATOR)[1]]
}

/**
 * Element à prendre d'une bibliothèque et à placer sur un quadrillage
 */
export class StoreElement {
    constructor(name, icon, setDragged) {
        this.name = name
        this.icon = icon
        this.setDragged = setDragged
    }

    get Display() {
        return <Draggable id={this.name} icon={this.icon} setDragged={this.setDragged}/>
    }
}

/**
 * Bibilothèque d'éléments  
 */
export class Store {
    constructor() {
        this.elements = []
    }

    addElement(newElement) {
        this.elements.push(newElement)
    }

    get Display() {
        let eltsAsDrag = this.elements.map(elt => elt.Display)
        return <div class="std-wrap">{eltsAsDrag}</div>
    }
}

/**
 * Tuile d'un quadrillage
 */
export class Tile {
    constructor(x, y, grid) {
        this.x = x
        this.y = y
        this.defaultContent()
        this.selected = false
        this.grid = grid
    }

    setId(id) {
        this.id = id
    }

    defaultContent() {
        this.content = [<i class="fa-duotone fa-circle"></i>]
    }

    setContent(content) {
        this.content = [content]
    }

    removeContent() {
        this.defaultContent()
    }

    select() {
        this.grid.unselectAll()
        this.selected = true
    }

    unselect() {
        this.selected = false
    }

    get Display() {
        return(
            <Droppable id={transformXYtoID(this.x, this.y)}>
                <div class={this.selected ? "red" : ""} onMouseDown={() => this.select()}>
                    {this.content}
                </div>
            </Droppable>)
    }
}

/**
 * Quadrillage complet
 */
export class Grid {
    constructor(x, y) {
        this.x = x
        this.y = y
        this.#constructTiles()
    }

    #constructTiles() {
        this.rows = []
        for(let i=0; i<this.x; i++) {
            let row = []
            for(let j=0; j<this.y; j++) {
                row.push(new Tile(i, j, this))
            }
            this.rows.push(row)
        }
    }

    get Tiles() {
        let tiles = []
        for(let row of this.rows) {
            tiles = tiles.concat(row)
        }
        return tiles
    }

    getTile(x, y) {
        for(let tile of this.Tiles) {
            if(tile.x == x && tile.y == y) {
                return tile
            }
        }
    }

    get Display() {
        let rowsDisp = []
        for(let i=0; i<this.x; i++) {
            let rowDisp = []
            for(let j=0; j<this.y; j++) {
                rowDisp.push(this.getTile(i, j)?.Display)
            }
            rowsDisp.push(<div class="std-row std-row-size">{rowDisp}</div>)
        }

        return <div class="std-col mg-top-1">{rowsDisp}</div>
    }

    unselectAll() {
        this.Tiles.forEach(tile => tile.unselect())
    }

    get Selected() {
        return this.Tiles.find(tile => tile.selected)
    }
}