import React, { useState, useEffect } from "react"
import { useDraggable } from "@dnd-kit/react"

import { displayText } from "../utils/text.js"
import { get } from "lodash"

export default function Draggable({id, setDragged, icon}) {

    const {ref} = useDraggable({
        id: id,
    })

    function onDrag() {
        setDragged({id:id, icon:icon})
    }

    function getClass() {
        return id.includes("-") ? "std-transparency std-small-icon std-col" : "std-transparency std-big-icon std-col"
    }

    return (
        <a ref={ref} class={getClass()} onMouseDown={() => onDrag()} title="">
            <i class={icon}></i>
        </a>
    )
}