import React, { useState } from "react"
import TextInput from "../../units/TextInput"
import RadioInput from "../../units/RadioInput"
import BooleanInput from "../../units/BooleanInput"

export default function SectionDetails(props) {

    let sizeOptions = [
        {name : 'Grand', value : 'grand'},
        {name : 'Moyen', value : 'moyen'},
        {name : 'Petit', value : 'petit'},
    ]

    return(
        <>
            <TextInput label={"Texte : "}/>
            <RadioInput label={"Taille du texte : "} options={sizeOptions}/>
            <BooleanInput label={"Encadré : "}/>
        </>
    )
}