import React, { useState } from "react"

import "../../css/style.css"
import "../../css/all.min.css"
import "../../css/duotone.min.css"

import { Store, StoreElement } from "../utils/classes.js"

import { displayText } from "../utils/text.js"

export default function CharacterStore({setDragged}) {

    let store = new Store()
    store.addElement(new StoreElement("section", "fa-regular fa-section", setDragged))
    store.addElement(new StoreElement("square1", "fa-regular fa-square-1", setDragged))
    store.addElement(new StoreElement("squarea", "fa-regular fa-square-a", setDragged))
    store.addElement(new StoreElement("input12", "fa-regular fa-input-numeric", setDragged))
    store.addElement(new StoreElement("inputab", "fa-regular fa-input-text", setDragged))
    store.addElement(new StoreElement("check", "fa-regular fa-square-check", setDragged))
    store.addElement(new StoreElement("ellipsish", "fa-regular fa-ellipsis-stroke", setDragged))
    store.addElement(new StoreElement("ellipsisv", "fa-regular fa-ellipsis-stroke-vertical", setDragged))
    store.addElement(new StoreElement("dropdown", "fa-regular fa-list-dropdown", setDragged))
    store.addElement(new StoreElement("table", "fa-regular fa-table", setDragged))
    store.addElement(new StoreElement("note", "fa-regular fa-note-sticky", setDragged))
    store.addElement(new StoreElement("image", "fa-regular fa-image", setDragged))

    return(
        <div class="std-vert-center text-title">
            {displayText("characterStore")}
            {store.Display}
        </div>
    ) 

}