import React, { useId } from "react"

export default function RadioInput({label, options, position}) {

    const id = useId()

    function inputs() {
        return options.map((opt, index) => 
        <span class="me-05">
            <input type="radio" name={id} id={index} value={opt.value}/>
            {opt.name}
        </span>)
    }

    return(
        <div class="text-input">
            {label}
            {inputs()}
        </div>
    )
}