import React, { useState } from "react"
import { displayText } from "../utils/text"
import TextInput from "../units/TextInput"
import SectionDetails from "./details/SectionDetails"

export default function CharacterWidgetDetails({grid}) {

    function widgetType() {
        switch(grid?.Selected?.id) {
            case "section":
                return <SectionDetails/>
            default:
                break
        }
    }

    return(
        <div class="text-title h-50 mg-top-2">
            {displayText("characterDetails")}
            {widgetType()}
        </div>
    )
}